const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Cloudflare Radar";
pres.title = "Cloudflare Radar 2024 Year in Review";
pres.subject = "Internet patterns and trends observed through Cloudflare's global network";

// Color palette: Midnight Executive / Cloudflare-inspired dark navy
const C = {
  navy: "0A1628",
  navyLight: "111F38",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  accentOrange: "F48120",
  accentBlue: "00A4E4",
  mutedText: "94A3B8",
  cardBg: "0F1D32",
  gridLine: "1E3A5F"
};

// Helper: make shadow fresh each time
function makeShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.2 };
}

// Slide 1: Title
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };
  // Decorative top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: C.accentOrange }
  });
  // Subtle background shape
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 3.8, w: "100%", h: 1.8,
    fill: { color: C.navyLight }
  });
  // Title
  slide.addText("Cloudflare Radar 2024 Year in Review", {
    x: 0.6, y: 1.6, w: 8.8, h: 1.2,
    fontSize: 40, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  // Subtitle
  slide.addText("A data-driven analysis of global Internet traffic, adoption trends, connectivity disruptions, and security threats", {
    x: 0.6, y: 2.9, w: 8.5, h: 0.8,
    fontSize: 18, color: C.iceBlue, fontFace: "Calibri",
    align: "left", valign: "top"
  });
  // Footer meta
  slide.addText("Technology Executives & Network Infrastructure Leaders", {
    x: 0.6, y: 4.2, w: 8.5, h: 0.4,
    fontSize: 14, color: C.mutedText, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Source: radar.cloudflare.com/year-in-review/2024", {
    x: 0.6, y: 4.6, w: 8.5, h: 0.3,
    fontSize: 12, color: C.mutedText, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
}

// Slide 2: 17% Global Traffic Growth and Starlink's 3.3x Surge
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: C.accentOrange }
  });
  slide.addText("17% Global Traffic Growth and Starlink's 3.3x Surge", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  // Left stat card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 4.2, h: 2.0,
    fill: { color: C.cardBg }, rectRadius: 0.06
  });
  slide.addText("17%", {
    x: 0.7, y: 1.2, w: 3.8, h: 0.9,
    fontSize: 60, bold: true, color: C.accentOrange, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Year-over-year growth in global Internet traffic during 2024", {
    x: 0.7, y: 2.05, w: 3.8, h: 0.9,
    fontSize: 16, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Right stat card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: 1.1, w: 4.5, h: 2.0,
    fill: { color: C.cardBg }, rectRadius: 0.06
  });
  slide.addText("3.3x", {
    x: 5.2, y: 1.2, w: 4.1, h: 0.9,
    fontSize: 60, bold: true, color: C.accentBlue, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Starlink traffic surge as satellite connectivity expands to underserved regions", {
    x: 5.2, y: 2.05, w: 4.1, h: 0.9,
    fontSize: 16, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Starlink image
  slide.addImage({
    path: "/app/benchmark/assets/starlink-traffic-growth-2024.jpg",
    x: 0.5, y: 3.3, w: 9, h: 2.0,
    sizing: { type: "contain", w: 9, h: 2.0 }
  });

  // Caption
  slide.addText("Normalized Starlink traffic worldwide showing 3.3x growth in 2024", {
    x: 0.5, y: 5.35, w: 9, h: 0.25,
    fontSize: 11, color: C.mutedText, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
}

// Slide 3: Google Leads Top 10 Services as Generative AI Rises
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: C.accentOrange }
  });
  slide.addText("Google Leads Top 10 Services as Generative AI Rises", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  // Table
  let tableData = [
    [
      { text: "Rank", options: { fill: { color: C.accentOrange }, color: C.white, bold: true, align: "center" } },
      { text: "Service", options: { fill: { color: C.accentOrange }, color: C.white, bold: true, align: "left" } }
    ],
    [{ text: "#1", options: { fill: { color: C.cardBg }, color: C.accentOrange, bold: true, align: "center" } }, { text: "Google", options: { fill: { color: C.cardBg }, color: C.white, align: "left" } }],
    [{ text: "#2", options: { fill: { color: C.navyLight }, color: C.accentOrange, bold: true, align: "center" } }, { text: "Facebook", options: { fill: { color: C.navyLight }, color: C.white, align: "left" } }],
    [{ text: "#3", options: { fill: { color: C.cardBg }, color: C.accentOrange, bold: true, align: "center" } }, { text: "Apple", options: { fill: { color: C.cardBg }, color: C.white, align: "left" } }],
    [{ text: "#4", options: { fill: { color: C.navyLight }, color: C.accentOrange, bold: true, align: "center" } }, { text: "TikTok", options: { fill: { color: C.navyLight }, color: C.white, align: "left" } }],
    [{ text: "#5", options: { fill: { color: C.cardBg }, color: C.accentOrange, bold: true, align: "center" } }, { text: "AWS", options: { fill: { color: C.cardBg }, color: C.white, align: "left" } }],
    [{ text: "#6", options: { fill: { color: C.navyLight }, color: C.accentOrange, bold: true, align: "center" } }, { text: "Microsoft", options: { fill: { color: C.navyLight }, color: C.white, align: "left" } }],
    [{ text: "#7", options: { fill: { color: C.cardBg }, color: C.accentOrange, bold: true, align: "center" } }, { text: "Instagram", options: { fill: { color: C.cardBg }, color: C.white, align: "left" } }],
    [{ text: "#8", options: { fill: { color: C.navyLight }, color: C.accentOrange, bold: true, align: "center" } }, { text: "YouTube", options: { fill: { color: C.navyLight }, color: C.white, align: "left" } }],
    [{ text: "#9", options: { fill: { color: C.cardBg }, color: C.accentOrange, bold: true, align: "center" } }, { text: "Amazon", options: { fill: { color: C.cardBg }, color: C.white, align: "left" } }],
    [{ text: "#10", options: { fill: { color: C.navyLight }, color: C.accentOrange, bold: true, align: "center" } }, { text: "WhatsApp", options: { fill: { color: C.navyLight }, color: C.white, align: "left" } }]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.1, w: 3.6, h: 4.0,
    border: { pt: 0.5, color: C.gridLine },
    colW: [1.0, 2.6],
    fontFace: "Calibri", fontSize: 14
  });

  // Right side image
  slide.addImage({
    path: "/app/benchmark/assets/top-10-internet-services.jpg",
    x: 4.4, y: 1.1, w: 5.1, h: 2.6,
    sizing: { type: "contain", w: 5.1, h: 2.6 }
  });

  // Insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.4, y: 3.9, w: 5.1, h: 1.2,
    fill: { color: C.cardBg }
  });
  slide.addText("Key Insight", {
    x: 4.6, y: 4.0, w: 4.7, h: 0.35,
    fontSize: 16, bold: true, color: C.accentOrange, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Generative AI continued its rapid rise throughout 2024, while the Metaverse receded into the background. Rankings based on aggregate data from Cloudflare's 1.1.1.1 DNS resolver.", {
    x: 4.6, y: 4.35, w: 4.7, h: 0.7,
    fontSize: 13, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });
}

// Slide 4: Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: C.accentOrange }
  });
  slide.addText("Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 30, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  // Left: PQE image
  slide.addImage({
    path: "/app/benchmark/assets/post-quantum-encryption-adoption.jpg",
    x: 0.5, y: 1.1, w: 5.0, h: 2.8,
    sizing: { type: "contain", w: 5.0, h: 2.8 }
  });
  slide.addText("Post-quantum encrypted traffic worldwide showing rapid adoption after Chrome 124 release", {
    x: 0.5, y: 3.95, w: 5.0, h: 0.3,
    fontSize: 11, color: C.mutedText, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  // Right: stat cards
  // PQE stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 1.1, w: 3.7, h: 1.15,
    fill: { color: C.cardBg }
  });
  slide.addText("2% → 13%", {
    x: 6.0, y: 1.15, w: 3.3, h: 0.55,
    fontSize: 32, bold: true, color: C.accentBlue, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Post-quantum encryption share of TLS 1.3 traffic after Chrome 124 default enablement (April 17)", {
    x: 6.0, y: 1.7, w: 3.3, h: 0.5,
    fontSize: 12, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // HTTP/3 stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 2.45, w: 3.7, h: 1.15,
    fill: { color: C.cardBg }
  });
  slide.addText("21%", {
    x: 6.0, y: 2.5, w: 3.3, h: 0.55,
    fontSize: 32, bold: true, color: C.accentOrange, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("of traffic uses HTTP/3, running on QUIC for faster, encrypted-by-default connections", {
    x: 6.0, y: 3.05, w: 3.3, h: 0.5,
    fontSize: 12, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Go stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 3.8, w: 3.7, h: 1.15,
    fill: { color: C.cardBg }
  });
  slide.addText("Go #1", {
    x: 6.0, y: 3.85, w: 3.3, h: 0.55,
    fontSize: 32, bold: true, color: C.iceBlue, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Go is the top API client language (~12%), followed by Node.js, Python (9.6%), Java (7.4%)", {
    x: 6.0, y: 4.4, w: 3.3, h: 0.5,
    fontSize: 12, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });
}

// Slide 5: 225 Major Disruptions: Government Shutdowns Lead Outage Causes
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: C.accentOrange }
  });
  slide.addText("225 Major Disruptions: Government Shutdowns Lead Outage Causes", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 28, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  // Big stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.05, w: 2.6, h: 1.6,
    fill: { color: C.cardBg }
  });
  slide.addText("225", {
    x: 0.7, y: 1.1, w: 2.2, h: 0.8,
    fontSize: 52, bold: true, color: C.accentOrange, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Major Internet disruptions observed globally in 2024", {
    x: 0.7, y: 1.85, w: 2.2, h: 0.7,
    fontSize: 14, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Bar chart
  let chartData = [{
    name: "Disruptions",
    labels: ["Govt Directed", "Cable Cut", "Unknown", "Power Outage", "Technical", "Military", "Weather", "Maintenance", "Cyber Attack", "Natural Disaster", "Fire"],
    values: [116, 41, 16, 16, 9, 9, 8, 4, 4, 1, 1]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 3.4, y: 1.05, w: 6.1, h: 3.4,
    barDir: "col",
    chartColors: [C.accentOrange],
    chartArea: { fill: { color: C.navy }, roundedCorners: false },
    catAxisLabelColor: C.mutedText,
    valAxisLabelColor: C.mutedText,
    valGridLine: { color: C.gridLine, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.white,
    showLegend: false,
    title: "Causes of Major Internet Disruptions (2024)",
    titleColor: C.white,
    titleFontSize: 14,
    titleBold: true
  });

  // Insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 2.85, w: 2.6, h: 1.6,
    fill: { color: C.cardBg }
  });
  slide.addText("Insight", {
    x: 0.7, y: 2.95, w: 2.2, h: 0.3,
    fontSize: 14, bold: true, color: C.accentBlue, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Government-directed shutdowns (116+) accounted for over half of all major disruptions, underscoring connectivity fragility from policy actions.", {
    x: 0.7, y: 3.25, w: 2.2, h: 1.1,
    fontSize: 12, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });
}

// Slide 6: 6.5% of Traffic Mitigated: Persistent Threats and Bot Concentration
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: C.accentOrange }
  });
  slide.addText("6.5% of Traffic Mitigated: Persistent Threats and Bot Concentration", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 28, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  // Top row stat cards
  const cardW = 2.9;
  const cardH = 1.3;
  const cardY = 1.05;
  const gap = 0.15;

  // Card 1
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: cardY, w: cardW, h: cardH,
    fill: { color: C.cardBg }
  });
  slide.addText("6.5%", {
    x: 0.65, y: cardY + 0.05, w: cardW - 0.3, h: 0.6,
    fontSize: 36, bold: true, color: C.accentOrange, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("of all traffic mitigated by Cloudflare", {
    x: 0.65, y: cardY + 0.65, w: cardW - 0.3, h: 0.55,
    fontSize: 13, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Card 2
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + cardW + gap, y: cardY, w: cardW, h: cardH,
    fill: { color: C.cardBg }
  });
  slide.addText("Gambling/Games", {
    x: 0.65 + cardW + gap, y: cardY + 0.05, w: cardW - 0.3, h: 0.6,
    fontSize: 24, bold: true, color: C.accentBlue, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("Most attacked industry sector", {
    x: 0.65 + cardW + gap, y: cardY + 0.65, w: cardW - 0.3, h: 0.55,
    fontSize: 13, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Card 3
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + 2 * (cardW + gap), y: cardY, w: cardW, h: cardH,
    fill: { color: C.cardBg }
  });
  slide.addText("68%", {
    x: 0.65 + 2 * (cardW + gap), y: cardY + 0.05, w: cardW - 0.3, h: 0.6,
    fontSize: 36, bold: true, color: C.iceBlue, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("of global bot traffic from top 10 countries", {
    x: 0.65 + 2 * (cardW + gap), y: cardY + 0.65, w: cardW - 0.3, h: 0.55,
    fontSize: 13, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Bottom row: two wider cards
  const bottomY = cardY + cardH + 0.25;
  const bCardW = 4.45;
  const bCardH = 1.6;

  // Log4j card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: bottomY, w: bCardW, h: bCardH,
    fill: { color: C.cardBg }
  });
  slide.addText("Log4j Persistence", {
    x: 0.65, y: bottomY + 0.1, w: bCardW - 0.3, h: 0.35,
    fontSize: 16, bold: true, color: C.accentOrange, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("CVE-2021-44228, disclosed December 2021, continues to be actively targeted by attackers more than two years later — underscoring the persistent nature of widely known vulnerabilities.", {
    x: 0.65, y: bottomY + 0.45, w: bCardW - 0.3, h: 1.05,
    fontSize: 13, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Email card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + bCardW + gap, y: bottomY, w: bCardW, h: bCardH,
    fill: { color: C.cardBg }
  });
  slide.addText("Email Security Threats", {
    x: 0.65 + bCardW + gap, y: bottomY + 0.1, w: bCardW - 0.3, h: 0.35,
    fontSize: 16, bold: true, color: C.accentBlue, fontFace: "Calibri",
    align: "left", valign: "middle"
  });
  slide.addText("4.3% of emails processed were malicious. Of those, 43% contained a deceptive link. The .bar TLD originated the largest share of malicious and spam email observed during the year.", {
    x: 0.65 + bCardW + gap, y: bottomY + 0.45, w: bCardW - 0.3, h: 1.05,
    fontSize: 13, color: C.white, fontFace: "Calibri",
    align: "left", valign: "top"
  });
}

// Slide 7: Five Takeaways Shaping the 2025 Internet Outlook
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.08,
    fill: { color: C.accentOrange }
  });
  slide.addText("Five Takeaways Shaping the 2025 Internet Outlook", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  const items = [
    { num: "01", title: "Traffic Growth Trajectory", desc: "Global Internet traffic grew 17% YoY, with Starlink traffic surging 3.3x as satellite connectivity expanded to underserved regions." },
    { num: "02", title: "Post-Quantum Momentum", desc: "Post-quantum encryption adoption leapt from ~2% to 13% of TLS 1.3 traffic following Chrome 124's default enablement in April 2024." },
    { num: "03", title: "Connectivity Fragility", desc: "Government-directed shutdowns remained the leading cause of the 225 major Internet disruptions observed, followed by cable cuts (41) and power outages (16)." },
    { num: "04", title: "Persistent Security Threats", desc: "6.5% of all traffic was mitigated, Gambling/Games was the most targeted sector, and Log4j exploitation persists years after disclosure." },
    { num: "05", title: "Evolving Developer Ecosystem", desc: "Go surpassed other languages to become the most popular API client language, capturing roughly 12% of automated API traffic." }
  ];

  const startY = 1.05;
  const itemH = 0.85;
  const gap = 0.12;

  items.forEach((item, i) => {
    let y = startY + i * (itemH + gap);
    // Background card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 9, h: itemH,
      fill: { color: C.cardBg }
    });
    // Number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 0.7, h: itemH,
      fill: { color: C.accentOrange }
    });
    slide.addText(item.num, {
      x: 0.5, y: y, w: 0.7, h: itemH,
      fontSize: 18, bold: true, color: C.white, fontFace: "Calibri",
      align: "center", valign: "middle"
    });
    // Title
    slide.addText(item.title, {
      x: 1.35, y: y + 0.08, w: 8.0, h: 0.3,
      fontSize: 15, bold: true, color: C.iceBlue, fontFace: "Calibri",
      align: "left", valign: "middle"
    });
    // Description
    slide.addText(item.desc, {
      x: 1.35, y: y + 0.38, w: 8.0, h: 0.42,
      fontSize: 12, color: C.white, fontFace: "Calibri",
      align: "left", valign: "top"
    });
  });
}

pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved /app/output/final_deck.pptx"))
  .catch(err => { console.error(err); process.exit(1); });

